(()=>{'use strict';const key='flightdesk-maintenance-v1',el=id=>document.getElementById(id);let state={version:1,events:[]},blocked=false;
function validate(x){if(!x||x.version!==1||!Array.isArray(x.events)||x.events.length>50000||x.events.some(e=>!e||typeof e.id!=='string'||typeof e.subject!=='string'||!['quarantine','return-to-service'].includes(e.action)||!Number.isFinite(Date.parse(e.at))||typeof e.reference!=='string'))throw Error('Invalid maintenance history');return x;}
function load(){try{state=validate(JSON.parse(localStorage.getItem(key)||'{"version":1,"events":[]}'));blocked=false;}catch{blocked=true;}}
function subjects(brief){const a=brief?.aircraftAsset,b=brief?.battery;return[...(a?.identifier?[{subject:'asset:'+a.identifier,name:'Aircraft '+a.identifier}]:a?.model?[{subject:'model:'+a.model,name:'Aircraft model '+a.model+' (asset ID not recorded)'}]:[]),...(b?.packIds?.length?b.packIds.map(id=>({subject:'pack:'+id,name:'Pack '+id})):b?.key?[{subject:'battery:'+b.key,name:'Battery/set '+b.name}]:[])];}
function outstanding(){const last=new Map(),all=[...state.events];try{const logs=JSON.parse(localStorage.getItem('flightdesk-sorties-v1')||'{"sorties":[]}');for(const sortie of logs.sorties||[])for(const d of sortie.debriefs||[])if(d.defect)for(const r of subjects(sortie.briefing))all.push({...r,id:'debrief-'+sortie.id+'-'+d.recordedAt,at:d.recordedAt,action:'quarantine',reference:d.note||'Recorded post-flight defect'});}catch{return[{subject:'unreadable-flight-history',name:'Flight/defect history unavailable',action:'quarantine',at:'not recorded',reference:'Recover the flight log before assessing equipment'}];}all.sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));for(const e of all)last.set(e.subject,e);return [...last.values()].filter(e=>e.action==='quarantine');}
function store(events){const next=validate({version:1,events:[...state.events,...events]});localStorage.setItem(key,JSON.stringify(next));state=next;render();window.updateFlightdeskDecision?.();}
window.flightAssetQuarantine=(brief,note)=>{if(blocked)throw Error('Maintenance history unavailable: stop and recover existing records before recording this defect');const entries=subjects(brief);if(!entries.length)throw Error('No recorded aircraft/battery identity: record affected equipment manually before its next use');store(entries.map(r=>({...r,id:crypto.randomUUID(),at:new Date().toISOString(),action:'quarantine',reference:String(note),appVersion:window.FLIGHTDESK_BUILD?.appVersion||null,briefingId:brief.id||null})));};
window.flightAssetHealth=battery=>{if(blocked||outstanding().some(r=>r.subject==='unreadable-flight-history'))return{blocked:true,reason:'Maintenance/flight history cannot be read'};const a={model:el('aircraftselect')?.value,identifier:el('assetidentity')?.value},ids=new Set(subjects({aircraftAsset:a,battery}).map(r=>r.subject));return{blocked:outstanding().some(r=>ids.has(r.subject)),items:outstanding().filter(r=>ids.has(r.subject))};};
const panel=document.createElement('details');panel.id='maintenancepanel';panel.innerHTML='<summary>Equipment follow-up / return to service</summary><p>Reported defects quarantine the recorded aircraft and packs conservatively. Follow the applicable manufacturer/operator procedure. A return-to-service record must identify the decision, checks/repair and reference; it does not certify a repair.</p><div id="maintenanceitems"></div><label><span class="label">Return-to-service decision / procedure reference · required when restoring an item</span><textarea id="maintenancereference" maxlength="2000"></textarea></label><p id="maintenancestatus" role="status"></p>';
el('postflightcard').querySelector('.body').append(panel);
function render(){el('maintenanceitems').replaceChildren();if(blocked){el('maintenancestatus').textContent='Existing maintenance history cannot be read. It has not been overwritten; preserve your backup.';return;}for(const r of outstanding()){const div=document.createElement('div'),p=document.createElement('p'),button=document.createElement('button');p.textContent=r.name+' · quarantined '+r.at+' · '+r.reference;button.type='button';button.className='btn';button.textContent='Record return to service · '+r.name;button.onclick=()=>{const ref=el('maintenancereference').value.trim();if(!ref){el('maintenancestatus').textContent='Enter the documented decision/procedure first.';return;}try{store([{...r,id:crypto.randomUUID(),at:new Date().toISOString(),action:'return-to-service',reference:ref}]);el('maintenancestatus').textContent='Return-to-service decision appended. Repeat the normal pre-flight checks.';}catch(e){el('maintenancestatus').textContent='Maintenance update NOT saved: '+e.message;}};div.append(p,button);el('maintenanceitems').append(div);}if(!outstanding().length)el('maintenancestatus').textContent='No unresolved defect quarantine in this maintenance history. This is not an inspection result.';}
load();render();window.addEventListener('flightdesk:restored',()=>{load();render();window.updateFlightdeskDecision?.();});
})();
